/bin/bash -lc "find / -type f \\( -name pvpython -o -name paraview -o -name '*TTK*' \\) 2>/dev/null | head -80; python3 - <<'PY'
try:
 import paraview
 print('paraview python', paraview.__file__)
except Exception as e: print('no paraview',e)
try:
 import vtk
 print('vtk',vtk.vtkVersion.GetVTKVersion())
except Exception as e: print('no vtk',e)
PY"

