/bin/bash -lc "/opt/conda/bin/pvpython - <<'PY' 2>&1 | tail -5
from paraview.simple import *
r=XMLImageDataReader(FileName=['/workspace/fracture.vti']);p=TTKPersistenceDiagram(Input=r);p.ScalarField=['POINTS','Scalars_'];t=Threshold(Input=p);t.Scalars=['CELLS','Persistence'];t.LowerThreshold=.05;t.UpperThreshold=1e99;s=TTKTopologicalSimplification(Domain=r,Constraints=t);s.ScalarField=['POINTS','Scalars_'];m=TTKMorseSmaleComplex(Input=s);m.ScalarField=['POINTS','Scalars_'];m.MorseSmaleComplexSegmentation=True;m.CriticalPoints=True;m.UpdatePipeline();
for o, arr in [(OutputPort(m,3),'MorseSmaleManifold'),(OutputPort(m,0),'CellDimension')]:
 o.UpdatePipeline(); info=o.GetDataInformation(); ai=info.GetPointDataInformation().GetArrayInformation(arr); print(arr,ai.GetComponentRange(0),info.GetNumberOfPoints())
PY"

